<script setup>
import {ref,computed,onMounted,watch,nextTick,onUnmounted} from 'vue';import {useRoute,useRouter} from 'vue-router';import ConfirmDialog from '../components/ConfirmDialog.vue';import Icon from '../components/common/Icon.vue';import {useUnsavedGuard} from '../composables/useUnsavedGuard.js';import {get,post,put,message} from '../services/api.js';import {useUi,useAuth} from '../stores/index.js';
const route=useRoute(),router=useRouter(),ui=useUi(),auth=useAuth(),edit=computed(()=>!!route.params.id),countries=ref([]),busy=ref(false),loading=ref(false),error=ref(''),errors=ref({}),dirty=ref(false),done=ref(false);const b=ref({name:'',cuisine:'',country:'',borough:'',city:'',address:{building:'',street:'',zipcode:''},grades:[],isFeatured:false,featuredStart:null,featuredEnd:null,profile:{tagline:'',story:'',signatureDishes:[],priceRange:'$$',openingHours:'',dressCode:'',reservations:'',dietaryOptions:[],tags:[],funFact:'',imageUrl:'',website:'',phone:'',email:''},priceLevel:2,status:'open',timezone:'Asia/Manila',hours:[],dietary:[],allergens:[],amenities:[],occasions:[],paymentMethods:[],social:{},menuPreview:[],gallery:[]});const imageFailed=ref(false);const lng=ref(''),lat=ref(''),dishes=ref(''),tags=ref(''),dietaryText=ref('');const hasDraft=ref(false),shake=ref(false);const draftKey='bonappefind_draft_'+(route.params.id||'new');let timer;
watch([b,lng,lat,dishes,tags,dietaryText],()=>{if(!loading.value){dirty.value=true;clearTimeout(timer);timer=setTimeout(()=>localStorage.setItem(draftKey,JSON.stringify({...b.value,address:{...b.value.address,...(lng.value!==''&&lat.value!==''?{coord:[Number(lng.value),Number(lat.value)]}:{coord:undefined})},profile:{...b.value.profile,signatureDishes:arr(dishes.value),tags:arr(tags.value),dietaryOptions:arr(dietaryText.value)}})),500);}},{deep:true});
function validate(){const e={},v=b.value;if(!v.name.trim())e.name='Enter the restaurant name.';if(!v.cuisine.trim())e.cuisine='Enter a cuisine, for example Filipino.';if(!v.borough.trim())e.borough='Enter the borough or region.';if(!v.country)e.country='Choose a country.';if(!v.address.street.trim())e['address.street']='Enter the street name.';
 if((lng.value==='')!==(lat.value===''))e['address.coord']='Enter both longitude and latitude, or leave both empty.';else if(lng.value!==''&&(!Number.isFinite(Number(lng.value))||Math.abs(Number(lng.value))>180||!Number.isFinite(Number(lat.value))||Math.abs(Number(lat.value))>90))e['address.coord']='Longitude must be −180 to 180; latitude must be −90 to 90.';
 v.grades.forEach((g,i)=>{if(!g.date)e['grades.'+i+'.date']='Choose a date.';if(g.score===''||g.score===null||!Number.isFinite(Number(g.score))||Number(g.score)<0||Number(g.score)>200)e['grades.'+i+'.score']='Score must be 0 to 200.';});
 for(const k of ['website','imageUrl']){const u=v.profile[k];if(u){try{if(k==='imageUrl'&&/^\/images\/(?:photos\/)?[a-z0-9-]+\.(?:svg|jpg|jpeg|png|webp)$/.test(u))continue;if(!/^https?:$/.test(new URL(u).protocol))throw 0;}catch{e['profile.'+k]='Enter a full link starting with https://';}}}
 if(v.profile.email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.profile.email))e['profile.email']='Enter an email address like name@example.com.';
 for(const k of ['facebook','instagram','tiktok','x']){const u=v.social[k];if(u){try{if(!/^https?:$/.test(new URL(u).protocol))throw 0;}catch{e['social.'+k]='Enter a full link starting with https://';}}}
 try{new Intl.DateTimeFormat('en',{timeZone:v.timezone});}catch{e.timezone='Choose a valid time zone.';}
 const used=new Set();v.hours.forEach((h,i)=>{if(used.has(h.day))e['hours.'+i]='This weekday already has a row. Use one row per day.';used.add(h.day);if(!h.closed&&(!/^([01]\d|2[0-3]):[0-5]\d$/.test(h.open)||!/^([01]\d|2[0-3]):[0-5]\d$/.test(h.close)))e['hours.'+i]='Choose opening and closing times, or mark this day closed.';});
 v.menuPreview.forEach((item,i)=>{if(!item.name?.trim())e['menuPreview.'+i+'.name']='Enter a dish name.';if(item.price===''||item.price==null||!Number.isFinite(Number(item.price))||Number(item.price)<0)e['menuPreview.'+i+'.price']='Enter a price of zero or more.';});
 if(v.isFeatured&&v.featuredStart&&v.featuredEnd&&v.featuredEnd<v.featuredStart)e.featuredEnd='End date must be on or after the start date.';
 return e;}
watch([b,lng,lat],()=>{if(Object.keys(errors.value).length){const now=validate();errors.value=Object.fromEntries(Object.entries(errors.value).filter(([k])=>now[k]).map(([k])=>[k,now[k]]));}},{deep:true});
const guard=useUnsavedGuard(()=>dirty.value&&!done.value);
function restoreDraft(){try{b.value=JSON.parse(localStorage.getItem(draftKey));if(b.value.address.coord)[lng.value,lat.value]=b.value.address.coord;else{lng.value='';lat.value='';}dishes.value=b.value.profile.signatureDishes?.join(', ')||'';tags.value=b.value.profile.tags?.join(', ')||'';dietaryText.value=b.value.profile.dietaryOptions?.join(', ')||'';ui.toast('Draft restored.');}catch{}hasDraft.value=false;}function discardDraft(){localStorage.removeItem(draftKey);hasDraft.value=false;}
function arr(s){return s.split(',').map(x=>x.trim()).filter(Boolean);}async function submit(){if(busy.value)return;error.value='';const found=validate();errors.value=found;if(Object.keys(found).length){shake.value=false;await nextTick();shake.value=true;setTimeout(()=>shake.value=false,500);const first=Object.keys(found)[0];const id=first.startsWith('grades.')?'grade-'+first.split('.')[2]+'-'+first.split('.')[1]:first.startsWith('hours.')?'hours-day-'+first.split('.')[1]:first.startsWith('menuPreview.')?'menu-'+first.split('.')[2]+'-'+first.split('.')[1]:{name:'restaurant-name',cuisine:'restaurant-cuisine',borough:'restaurant-borough',country:'restaurant-country','address.street':'address-street','address.coord':'longitude'}[first]||('profile-'+first.split('.').pop());(document.getElementById(id)||document.querySelector('[aria-invalid=true]'))?.focus();error.value='Please fix the highlighted fields and try again.';return;}busy.value=true;try{const body=structuredClone(JSON.parse(JSON.stringify(b.value)));body.profile.signatureDishes=arr(dishes.value);body.profile.tags=arr(tags.value);body.profile.dietaryOptions=arr(dietaryText.value);body.profile.priceRange='$'.repeat(Number(body.priceLevel));if(lng.value!==''||lat.value!=='')body.address.coord=[Number(lng.value),Number(lat.value)];else delete body.address.coord;for(const g of body.grades)g.score=Number(g.score);body.menuPreview=body.menuPreview.map(item=>({...item,name:item.name.trim(),price:Number(item.price)}));const r=edit.value?await put('/restaurants/'+route.params.id,body):await post('/restaurants',body);done.value=true;dirty.value=false;clearTimeout(timer);localStorage.removeItem(draftKey);ui.toast(edit.value?'Changes saved.':r.data.approvalStatus==='pending'?'Restaurant saved. It is awaiting approval.':'Restaurant added. It is now saved in the database.');router.push('/restaurants/'+r.data._id);}catch(e){error.value=message(e);for(const x of e.response?.data?.errors||[])errors.value[x.field]=x.message;}finally{busy.value=false;}}
function addGrade(){b.value.grades.push({date:new Date().toISOString().slice(0,10),grade:'A',score:0});}function addHours(){const day=[1,2,3,4,5,6,0].find(day=>!b.value.hours.some(h=>h.day===day));if(day===undefined)return;b.value.hours.push({day,open:'10:00',close:'21:00',closed:false});}
onUnmounted(()=>clearTimeout(timer));watch(()=>b.value.profile.imageUrl,()=>imageFailed.value=false);
onMounted(async()=>{loading.value=true;try{countries.value=(await get('/countries')).data;if(edit.value){const data=(await get('/restaurants/'+route.params.id)).data;b.value={...b.value,...data,profile:{...b.value.profile,...data.profile},address:{...b.value.address,...data.address},social:data.social||{}};for(const key of ['featuredStart','featuredEnd'])b.value[key]=b.value[key]?.slice(0,10)||null;b.value.grades=b.value.grades.map(g=>({...g,date:g.date?.slice(0,10)}));}else if(localStorage.getItem(draftKey))hasDraft.value=true;if(b.value.address.coord){[lng.value,lat.value]=b.value.address.coord;}dishes.value=b.value.profile.signatureDishes?.join(', ')||'';tags.value=b.value.profile.tags?.join(', ')||'';dietaryText.value=b.value.profile.dietaryOptions?.join(', ')||'';}catch(e){error.value=message(e);}finally{loading.value=false;dirty.value=false;}});
const basic=[['name','Restaurant name *','Kusina ni Lola Pacing'],['cuisine','Cuisine *','Filipino'],['borough','Borough or region *','Pampanga'],['city','City','San Fernando']];const profile=[['tagline','Tagline',80],['story','Story',600],['openingHours','Opening hours',200],['dressCode','Dress code',100],['reservations','Reservations',200],['funFact','Fun fact',200],['imageUrl','Image link',1000],['website','Website',1000],['phone','Phone',100],['email','Restaurant email',150]];
</script>
<template><div class="container section restaurant-form"><div class="page-head"><h1>{{edit?'Edit '+b.name:'Add a restaurant'}}</h1><p>Share a place worth eating at. Fields marked with an asterisk are required.</p><p v-if="!auth.user" class="muted">Please <RouterLink to="/login">log in</RouterLink> as an owner or administrator to save a restaurant.</p></div><p v-if="error" role="alert" class="form-status error">{{error}}</p><div v-if="loading" class="skeleton" aria-busy="true" style="min-height:320px"></div><div v-if="hasDraft&&!loading" class="form-status success draft-bar" role="status"><span>You have an unsaved draft of this form.</span><span class="row"><button type="button" class="small" @click="restoreDraft">Restore draft</button><button type="button" class="secondary small" @click="discardDraft">Discard</button></span></div><form v-if="!loading" novalidate @submit.prevent="submit" class="stack" :class="{shake}" :aria-busy="busy"><fieldset :disabled="busy" class="form-fields"><section class="card pad"><h2>The basics</h2><div class="form-grid"><div v-for="[key,label,placeholder] in basic" :key="key"><label :for="'restaurant-'+key">{{label}}</label><input :id="'restaurant-'+key" v-model="b[key]" :placeholder="placeholder" :maxlength="key==='name'?120:150" :aria-invalid="!!errors[key]"><p v-if="errors[key]" class="field-msg">{{errors[key]}}</p></div><div><label for="restaurant-country">Country *</label><select id="restaurant-country" v-model="b.country" :aria-invalid="!!errors.country"><option value="">Choose a country</option><option v-for="c in countries" :key="c.slug">{{c.name}}</option><option v-if="b.country&&!countries.some(c=>c.name===b.country)">{{b.country}}</option></select><p class="field-msg">{{errors.country}}</p></div><div><label for="restaurant-status">Status</label><select id="restaurant-status" v-model="b.status"><option value="open">Open</option><option value="temporarily_closed">Temporarily Closed</option><option value="permanently_closed">Permanently Closed</option></select></div></div></section><section class="card pad"><h2>Address</h2><div class="form-grid"><div v-for="[key,label] in [['building','Building number'],['street','Street *'],['zipcode','Zip or postal code']]" :key="key"><label :for="'address-'+key">{{label}}</label><input :id="'address-'+key" v-model="b.address[key]" :aria-invalid="!!errors['address.'+key]"><p class="field-msg">{{errors['address.'+key]}}</p></div><div><label for="longitude">Longitude</label><input id="longitude" v-model="lng" :aria-invalid="!!errors['address.coord']" type="number" step="any" min="-180" max="180"></div><div><label for="latitude">Latitude</label><input id="latitude" v-model="lat" :aria-invalid="!!errors['address.coord']" type="number" step="any" min="-90" max="90"></div></div><p class="field-msg">{{errors['address.coord']}}</p></section><section class="card pad"><div class="row between"><h2>Grades and scores</h2><button type="button" class="secondary" @click="addGrade">Add a grade</button></div><div v-for="(g,i) in b.grades" :key="i" class="grade-row"><div style="flex:1"><label :for="'grade-date-'+i">Date</label><input :id="'grade-date-'+i" v-model="g.date" type="date" :aria-invalid="!!errors['grades.'+i+'.date']"><p class="field-msg">{{errors['grades.'+i+'.date']}}</p></div><div style="width:90px"><label :for="'grade-letter-'+i">Grade</label><select :id="'grade-letter-'+i" v-model="g.grade"><option>A</option><option>B</option><option>C</option><option>Z</option></select></div><div style="width:100px"><label :for="'grade-score-'+i">Score</label><input :id="'grade-score-'+i" v-model="g.score" type="number" min="0" max="200" :aria-invalid="!!errors['grades.'+i+'.score']"><p class="field-msg">{{errors['grades.'+i+'.score']}}</p></div><button type="button" class="secondary" @click="b.grades.splice(i,1)">Remove</button></div></section><section class="card pad"><h2>Profile and story</h2><div v-for="[key,label,max] in profile" :key="key" class="field"><label :for="'profile-'+key">{{label}}</label><textarea v-if="key==='story'" :id="'profile-'+key" v-model="b.profile[key]" :maxlength="max"></textarea><input v-else :type="key==='email'?'email':key==='phone'?'tel':'text'" :inputmode="['website','imageUrl'].includes(key)?'url':undefined" :placeholder="key==='openingHours'?'Mon–Sat, 10:00 AM–9:00 PM':key==='website'?'https://example.com':undefined" :id="'profile-'+key" v-model="b.profile[key]" :maxlength="max" :aria-invalid="!!errors['profile.'+key]"><p class="field-msg">{{errors['profile.'+key]}}</p></div><figure v-if="b.profile.imageUrl&&!imageFailed" class="image-preview"><img :src="b.profile.imageUrl" alt="Restaurant image preview" @error="imageFailed=true"><figcaption>Image preview</figcaption></figure><p v-if="imageFailed" class="field-msg" role="status">This image could not be loaded. Check the image link.</p><div class="field"><label for="signature-dishes">Signature dishes (separate with commas)</label><input id="signature-dishes" v-model="dishes"></div><div class="field"><label for="profile-tags">Tags (separate with commas)</label><input id="profile-tags" v-model="tags"></div><div class="field"><label for="dietary-text">Dietary information (separate with commas)</label><input id="dietary-text" v-model="dietaryText"></div><label for="price-level">Price range</label><select id="price-level" v-model.number="b.priceLevel"><option v-for="n in 4" :key="n" :value="n">{{'$'.repeat(n)}}</option></select></section><section class="card pad"><h2>Extra details</h2><div v-if="auth.staff" class="field"><label><input v-model="b.isFeatured" type="checkbox"> Feature on the home page</label><label for="featured-start">Featured start (optional)</label><input id="featured-start" v-model="b.featuredStart" type="date"><label for="featured-end">Featured end (optional)</label><input id="featured-end" v-model="b.featuredEnd" type="date" :min="b.featuredStart||undefined" :aria-invalid="!!errors.featuredEnd"><p v-if="errors.featuredEnd" class="field-msg">{{errors.featuredEnd}}</p></div><div class="field"><label for="timezone">Time zone (IANA name)</label><select id="timezone" v-model="b.timezone" :aria-invalid="!!errors.timezone"><option v-for="zone in ['Asia/Manila','Asia/Singapore','Asia/Tokyo','America/New_York','America/Los_Angeles','Europe/London','UTC']" :key="zone" :value="zone">{{zone.replaceAll('_',' ')}}</option><option v-if="b.timezone&&!['Asia/Manila','Asia/Singapore','Asia/Tokyo','America/New_York','America/Los_Angeles','Europe/London','UTC'].includes(b.timezone)" :value="b.timezone">{{b.timezone}}</option></select><p class="field-msg">{{errors.timezone}}</p></div><div class="row between"><h3>Weekly opening hours</h3><button type="button" class="secondary" :disabled="b.hours.length>=7" @click="addHours">Add hours</button></div><p class="small muted">Add one row per day. Mark days closed to disable time fields. A closing time earlier than the opening time means the restaurant closes the next day.</p><div v-for="(h,i) in b.hours" :key="i" class="hours-row"><div class="field"><label :for="'hours-day-'+i">Day</label><select :id="'hours-day-'+i" v-model.number="h.day" :aria-invalid="!!errors['hours.'+i]"><option v-for="(day,n) in ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday']" :key="day" :value="n" :disabled="b.hours.some((row,index)=>index!==i&&row.day===n)">{{day}}</option></select></div><div class="field"><label :for="'hours-open-'+i">Opens</label><input :id="'hours-open-'+i" v-model="h.open" type="time" :disabled="h.closed"></div><div class="field"><label :for="'hours-close-'+i">Closes</label><input :id="'hours-close-'+i" v-model="h.close" type="time" :disabled="h.closed"></div><label class="check-option"><input v-model="h.closed" type="checkbox"> Closed</label><button type="button" class="secondary" :aria-label="'Remove hours row '+(i+1)" @click="b.hours.splice(i,1)">Remove</button><p v-if="errors['hours.'+i]" class="field-msg row-error">{{errors['hours.'+i]}}</p></div><h3>Dietary tags</h3><div class="option-grid"><label class="check-option" v-for="x in ['Halal','Vegan','Vegetarian','Gluten-Free','Dairy-Free','Nut-Free','Pescatarian','Kosher']" :key="x"><input v-model="b.dietary" type="checkbox" :value="x"> {{x}}</label></div><h3>Amenities</h3><div class="option-grid"><label class="check-option" v-for="x in ['Wi-Fi','Parking','Outdoor seating','Kid-friendly','Pet-friendly','Air-conditioned','Private room']" :key="x"><input v-model="b.amenities" type="checkbox" :value="x"> {{x}}</label></div><h3>Payment methods</h3><div class="option-grid"><label class="check-option" v-for="x in ['Cash','Card','E-wallet']" :key="x"><input v-model="b.paymentMethods" type="checkbox" :value="x"> {{x}}</label></div><h3>Social links</h3><div v-for="key in ['facebook','instagram','tiktok','x']" :key="key" class="field"><label :for="'social-'+key">{{key}}</label><input :id="'social-'+key" v-model="b.social[key]" type="text" inputmode="url" :aria-invalid="!!errors['social.'+key]"><p class="field-msg">{{errors['social.'+key]}}</p></div><h3>Menu preview</h3><div v-for="(item,i) in b.menuPreview" :key="i" class="menu-row"><div class="field"><label :for="'menu-name-'+i">Dish name</label><input :id="'menu-name-'+i" v-model="item.name" maxlength="120" placeholder="e.g. Chicken adobo" :aria-invalid="!!errors['menuPreview.'+i+'.name']"><p v-if="errors['menuPreview.'+i+'.name']" class="field-msg">{{errors['menuPreview.'+i+'.name']}}</p></div><div class="field"><label :for="'menu-price-'+i">Price (local currency)</label><input :id="'menu-price-'+i" v-model="item.price" type="number" min="0" step=".01" placeholder="0.00" :aria-invalid="!!errors['menuPreview.'+i+'.price']"><p v-if="errors['menuPreview.'+i+'.price']" class="field-msg">{{errors['menuPreview.'+i+'.price']}}</p></div><div class="field"><label :for="'menu-description-'+i">Description (optional)</label><input :id="'menu-description-'+i" v-model="item.description" maxlength="300" placeholder="Short description"></div><button type="button" class="secondary" :aria-label="'Remove menu item '+(i+1)" @click="b.menuPreview.splice(i,1)">Remove</button></div><button type="button" class="secondary" @click="b.menuPreview.push({name:'',price:0,description:''})">Add menu item</button></section><div class="row"><button class="cta" :class="{'is-loading':busy}" :disabled="busy||loading"><span>{{edit?'Save changes':'Save restaurant'}}</span></button><RouterLink class="btn secondary" to="/restaurants">Cancel</RouterLink></div></fieldset></form><ConfirmDialog v-if="guard.pending.value" title="Leave without saving?" text="You have unsaved changes on this form. If you leave now they will be lost, although a draft is kept in this browser for new listings." confirm-label="Leave page" cancel-label="Keep editing" @cancel="guard.stay" @confirm="guard.leave"/></div></template>

<style scoped>
.restaurant-form{max-width:1000px}.form-fields{border:0;padding:0;margin:0;min-width:0;display:grid;gap:24px}.restaurant-form .card{min-width:0}.restaurant-form h2{margin-top:0}.restaurant-form h3{margin-top:28px}.restaurant-form label{display:block;margin-bottom:7px;font-weight:600}.restaurant-form input:not([type=checkbox]),.restaurant-form select,.restaurant-form textarea{width:100%;min-width:0}.restaurant-form .field{min-width:0}.restaurant-form .field-msg:empty{display:none}.grade-row,.hours-row,.menu-row{display:grid;align-items:start;gap:14px;padding:18px;margin:14px 0;border:1px solid var(--color-border);border-radius:14px;background:var(--color-bg)}.grade-row{grid-template-columns:minmax(0,2fr) minmax(0,1fr) minmax(0,1fr) auto}.grade-row>div{width:auto!important;min-width:0}.hours-row{grid-template-columns:minmax(0,1.4fr) repeat(2,minmax(0,1fr)) auto auto}.menu-row{grid-template-columns:minmax(0,1.4fr) minmax(0,1fr) minmax(0,1.5fr) auto}.grade-row>button,.hours-row>button,.menu-row>button{margin-top:29px}.option-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px}.restaurant-form .check-option{display:flex;align-items:center;gap:9px;margin:0;padding:12px;border:1px solid var(--color-border);border-radius:10px;background:var(--color-bg);cursor:pointer}.check-option:has(input:checked){border-color:var(--forestry);background:var(--color-chip)}.check-option input{width:18px;height:18px;flex-shrink:0}.hours-row .check-option{margin-top:29px}.row-error{grid-column:1/-1}.image-preview{margin:16px 0}.image-preview img{display:block;width:100%;height:220px;object-fit:cover;border-radius:14px}.image-preview figcaption{font-size:13px;color:var(--color-muted);margin-top:7px}
@media(max-width:760px){.grade-row,.hours-row,.menu-row{grid-template-columns:1fr 1fr}.grade-row>button,.hours-row>button,.menu-row>button,.hours-row .check-option{margin-top:0}.menu-row>.field:first-child{grid-column:1/-1}}
@media(max-width:480px){.grade-row,.hours-row,.menu-row,.option-grid,.restaurant-form .form-grid{grid-template-columns:1fr}.restaurant-form .card{padding:18px}.restaurant-form .row{gap:12px;flex-wrap:wrap}}
</style>
